'use server'

import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

const preferenceCookie = 'notifications-enabled'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get(preferenceCookie)?.value === 'true'

  cookieStore.set(preferenceCookie, String(!enabled), {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    path: '/',
    maxAge: 60 * 60 * 24 * 365,
  })

  refresh()
}

